class FitnessTracker:
    # Replace Magic Number with Symbolic Constant
    BMALE_CALORIE_FACTOR_SEDENTARY = 1.2
    BMALE_CALORIE_FACTOR_MILDLY_ACTIVE = 1.375
    BMALE_CALORIE_FACTOR_MODERATELY_ACTIVE = 1.55
    BMALE_CALORIE_FACTOR_VERY_ACTIVE = 1.725
    BMALE_CALORIE_FACTOR_EXTRA_ACTIVE = 1.9

    BFEMALE_CALORIE_FACTOR_SEDENTARY = 1.2
    BFEMALE_CALORIE_FACTOR_MILDLY_ACTIVE = 1.375
    BFEMALE_CALORIE_FACTOR_MODERATELY_ACTIVE = 1.55
    BFEMALE_CALORIE_FACTOR_VERY_ACTIVE = 1.725
    BFEMALE_CALORIE_FACTOR_EXTRA_ACTIVE = 1.9

    def __init__(self, height, weight, age, sex) -> None:
        self.height = height
        self.weight = weight
        self.age = age
        self.sex = sex
        self.BMI_std = [
            {"male": [20, 25]},
            {"female": [19, 24]}
        ]

    def get_BMI(self):
        return self.weight / self.height ** 2

    def condition_judge(self):
        # Replace Temp with Query
        if self.sex == "male":
            BMI_range = self.BMI_std[0]["male"]
        else:
            BMI_range = self.BMI_std[1]["female"]
        if self.get_BMI() > BMI_range[1]:
            # too fat
            return 1
        elif self.get_BMI() < BMI_range[0]:
            # too thin
            return -1
        else:
            # normal
            return 0

    def calculate_calorie_intake(self):
        if self.sex == "male":
            # Extract Method
            bmr = self._calculate_male_bmr()
        else:
            # Extract Method
            bmr = self._calculate_female_bmr()

        # Replace Parameter with Method Call (avoid multiple calls to condition_judge)
        condition = self.condition_judge()

        if condition == 1:
            calorie_intake = bmr * self.BMALE_CALORIE_FACTOR_MILDLY_ACTIVE
        elif condition == -1:
            calorie_intake = bmr * self.BMALE_CALORIE_FACTOR_VERY_ACTIVE
        else:
            calorie_intake = bmr * self.BMALE_CALORIE_FACTOR_MODERATELY_ACTIVE
        return calorie_intake

    def _calculate_male_bmr(self):
        return 10 * self.weight + 6.25 * self.height - 5 * self.age + 5

    def _calculate_female_bmr(self):
        return 10 * self.weight + 6.25 * self.height - 5 * self.age - 161
